{
  "meta": {
    "source": "e-MAG v3.1 — Modelo de Acessibilidade em Governo Eletrônico",
    "authority": "Ministério do Planejamento, Desenvolvimento e Gestão — Brasil",
    "url": "https://emag.governoeletronico.gov.br/",
    "note": "Mandatory for all Brazilian federal government websites. Based on WCAG 2.0 with government-specific additions. All gov.br portals must comply."
  },
  "section": {
    "title": "Marcação",
    "rules": [
      {
        "id": "1.1",
        "title": "Respeitar os padrões web",
        "description": "Follow W3C standards for HTML, XML, XHTML, and CSS. Code must be semantically correct and valid.",
        "wcag": null
      },
      {
        "id": "1.2",
        "title": "Organizar o código HTML de forma lógica e semântica",
        "description": "Structure HTML logically using semantic elements (headings, lists, emphasis). Reading order must match visual order.",
        "wcag": null
      },
      {
        "id": "1.3",
        "title": "Utilizar corretamente os níveis de cabeçalho",
        "description": "Heading hierarchy (H1–H6) must be logical. H1 for primary content, subsequent levels for subordinate sections. Do not skip levels.",
        "wcag": "1.3.1"
      },
      {
        "id": "1.4",
        "title": "Ordenar de forma lógica e intuitiva a leitura e tabulação",
        "description": "HTML code reading order must be logical. Main content should appear before navigation in source order.",
        "wcag": "1.3.2, 2.4.3"
      },
      {
        "id": "1.5",
        "title": "Fornecer âncoras para ir direto a um bloco de conteúdo",
        "description": "Provide skip links in the accessibility bar. First link must jump to main content.",
        "wcag": "2.4.1"
      },
      {
        "id": "1.6",
        "title": "Não utilizar tabelas para diagramação",
        "description": "Tables for tabular data only. Use CSS for layout.",
        "wcag": "1.3.1"
      },
      {
        "id": "1.7",
        "title": "Separar links adjacentes",
        "description": "Consecutive links must be separated by lists or delimiters to prevent confusion for screen reader users.",
        "wcag": null
      },
      {
        "id": "1.8",
        "title": "Dividir as áreas de informação",
        "description": "Pages must have distinct, consistent sections (header, navigation, content, footer) with landmark roles.",
        "wcag": "1.3.1, 2.4.6"
      },
      {
        "id": "1.9",
        "title": "Não abrir novas instâncias sem a solicitação do usuário",
        "description": "Do not use pop-ups, new windows, or target='_blank' unless explicitly requested by the user.",
        "wcag": "3.2.1, 3.2.2"
      }
    ]
  }
}
